def function(inputs, parameters, context):
    import pandas as pd
    df = inputs['cleaned']
    days = df['dteday'].nunique()
    total_rentals = df['cnt'].sum()
    average_daily_rentals = df['cnt'].mean()
    rolling_mean_7 = df['cnt'].rolling(window=7, min_periods=1).mean()
    df['rolling_mean_7'] = rolling_mean_7
    daily_demand = df[['dteday', 'cnt', 'rolling_mean_7']]
    rider_mix = {'option': {'xAxis': {'data': df['dteday'].dt.strftime('%Y-%m-%d').tolist()}, 'yAxis': {'type': 'value'}, 'series': [{'name': 'Casual', 'type': 'line', 'data': df['casual'].tolist(), 'stack': 'riders', 'areaStyle': {}}, {'name': 'Registered', 'type': 'line', 'data': df['registered'].tolist(), 'stack': 'riders', 'areaStyle': {}}]}}
    calendar_pattern = {'option': {'xAxis': {'data': list(range(1, 13))}, 'yAxis': {'data': list(range(7))}, 'visualMap': {'min': 0, 'max': float(df['cnt'].max()), 'inRange': {'color': ['#eff6ff', '#245bd7']}}, 'series': [{'type': 'heatmap', 'data': [[int(month)-1, int(day), float(value)] for (month, day), value in df.groupby(['mnth', 'weekday'])['cnt'].mean().items()]}]}}
    daily_detail = daily_demand
    return {'days': days, 'total_rentals': total_rentals, 'average_daily_rentals': round(average_daily_rentals, 2), 'daily_demand': daily_demand, 'rider_mix': rider_mix, 'calendar_pattern': calendar_pattern, 'daily_detail': daily_detail}
